//go:build ignore

// Generator for the domain inspector evaluation corpus.
//
//	go run internal/edr/testdata/gen_domain_corpus.go internal/edr/testdata
//
// It writes domain_benign.txt and domain_dga.txt. Everything the generator
// produces is SYNTHETIC: the DGA names come from simple generators written for
// this repository (not from real malware families or feeds), and part of the
// benign set is generated from a held-out word list. The hand-written benign
// names are real-looking domains chosen by the author, including deliberately
// awkward ones (CDN hashes, long legitimate subdomains). Output is
// deterministic (fixed seeds).
package main

import (
	"fmt"
	"math/rand"
	"os"
	"path/filepath"
	"strings"
)

