// Held-out words: chosen to be absent from the embedded model vocabulary, so
// generated benign names exercise words the model has not seen.
var heldOut = strings.Fields(`
quokka zeppelin marmalade pumpernickel kazoo wombat fandango gazebo hullabaloo juggernaut kumquat lollipop
mongoose nutmeg ocarina periwinkle quagmire rhubarb saxophone tarantula ukulele vermicelli walrus xylophone
yodel zucchini abacus bazooka cumulus dirigible espresso flamingo gherkin hedgehog iguana jackfruit kangaroo
lemur mandolin nebula octopus platypus quince raccoon salamander trombone umbra vortex whimsy yeti zigzag
bonsai cobbler dumpling emporium fiddle gumdrop harmonica igloo jamboree kayak lantern mosaic nimbus
outpost pagoda quiver rickshaw sundial teapot utopia vineyard windmill yonder zenith anvil bellows cobweb
driftwood eclipse fjord gondola hammock inkwell jetty kiosk lighthouse monsoon nutcracker orchestra pinwheel
quilter rowboat sailboat tinsel urchin velcro wigwam
`)

var tlds = []string{"com", "net", "org", "info", "io", "co", "biz", "us", "de", "uk"}
var dgaTLDs = []string{"com", "net", "org", "info", "biz", "ru", "cn", "top", "xyz", "cc", "pw", "tk", "click", "online"}

const letters = "abcdefghijklmnopqrstuvwxyz"

func randStr(r *rand.Rand, alphabet string, n int) string {
	b := make([]byte, n)
	for i := range b {
		b[i] = alphabet[r.Intn(len(alphabet))]
	}
	return string(b)
}

// Words used by the dictionary-concatenation DGA family (generator's own list).
var dgaWords = strings.Fields(`
able account across active actor adult agent alarm album angle animal answer apple arrow aspect basic beach
berry black blue board bridge brown camera candle carbon castle chain chair cloud coffee copper corner
cotton country dance dragon dream drift eagle earth engine fabric family farmer feather field flame forest
garden glass golden grand green harbor honey island jacket kitchen ladder lemon light marble meadow mirror
mountain office orange paper pepper planet pocket quiet river rocket silver simple spring stone summer
table thunder timber travel valley window winter yellow
`)

func main() {
	dir := "internal/edr/testdata"
	if len(os.Args) > 1 {
		dir = os.Args[1]
	}
	// ---- benign ----
	r := rand.New(rand.NewSource(20260101))
	var benign []string
	benign = append(benign, benignReal...)
	benign = append(benign, benignTricky...)
	seen := map[string]bool{}
	for _, b := range benign {
		seen[b] = true
	}
	add := func(s string) {
		if !seen[s] {
			seen[s] = true
			benign = append(benign, s)
		}
	}
	for i := 0; len(benign) < 330 && i < 5000; i++ {
		a := heldOut[r.Intn(len(heldOut))]
		t := tlds[r.Intn(len(tlds))]
		switch r.Intn(4) {
		case 0:
			add(a + "." + t)
		case 1:
			add(a + "-" + heldOut[r.Intn(len(heldOut))] + "." + t)
		case 2:
			add(a + heldOut[r.Intn(len(heldOut))] + "." + t)
		case 3:
			add([]string{"www", "shop", "blog", "mail", "app"}[r.Intn(5)] + "." + a + "." + t)
		}
	}
	// ---- synthetic DGA ----
	r = rand.New(rand.NewSource(20260202))
	var dga []string
	dseen := map[string]bool{}
	addD := func(s string) {
		if !dseen[s] {
			dseen[s] = true
			dga = append(dga, s)
		}
	}
	tld := func() string { return dgaTLDs[r.Intn(len(dgaTLDs))] }
	for i := 0; i < 110; i++ { // family 1: random letters
		addD(randStr(r, letters, 8+r.Intn(13)) + "." + tld())
	}
	for i := 0; i < 70; i++ { // family 1b: short random letters (hard)
		addD(randStr(r, letters, 6+r.Intn(3)) + "." + tld())
	}
	for i := 0; i < 70; i++ { // family 2: dictionary concatenation
		n := 2 + r.Intn(3)
		var ws []string
		for j := 0; j < n; j++ {
			ws = append(ws, dgaWords[r.Intn(len(dgaWords))])
		}
		addD(strings.Join(ws, "") + "." + tld())
	}
	for i := 0; i < 60; i++ { // family 3: hex
		addD(randStr(r, "0123456789abcdef", 12+r.Intn(21)) + "." + tld())
	}
	for i := 0; i < 60; i++ { // family 4: base32
		addD(randStr(r, "abcdefghijklmnopqrstuvwxyz234567", 14+r.Intn(13)) + "." + tld())
	}
	for i := 0; i < 40; i++ { // family 5: letters+digits
		addD(randStr(r, "abcdefghijklmnopqrstuvwxyz0123456789", 9+r.Intn(10)) + "." + tld())
	}
	write(filepath.Join(dir, "domain_benign.txt"),
		"# Benign-looking evaluation set. Hand-written real-looking names (including tricky CDN/long-subdomain cases)\n# plus names generated from a held-out word list. Label 0 = benign. See docs/domain-inspector.md.\n", benign)
	write(filepath.Join(dir, "domain_dga.txt"),
		"# SYNTHETIC DGA-style names from simple generators written for this repo (random letters, short random,\n# dictionary concatenation, hex, base32, alnum). NOT real malware domains. Label 1 = DGA-like.\n", dga)
	fmt.Println("benign", len(benign), "dga", len(dga))
}

func write(path, header string, lines []string) {
	if err := os.WriteFile(path, []byte(header+strings.Join(lines, "\n")+"\n"), 0o644); err != nil {
		panic(err)
	}
}
